import ast

user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for pandas import
found_pandas = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'pandas' for name in node.names):
        found_pandas = True
    if isinstance(node, ast.ImportFrom) and node.module == 'pandas':
        found_pandas = True

if not found_pandas:
    raise AssertionError('Task 1: Missing import pandas')

# Check for pd.DataFrame()
found_df = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
        if isinstance(node.func.value, ast.Name) and node.func.value.id == 'pd' and node.func.attr == 'DataFrame':
            found_df = True

if not found_df:
    raise AssertionError('Task 2: Missing pd.DataFrame() call')

# Check for double bracket column selection - look for pattern emp_df[[...]]
code_str = user_code.replace(' ', '').replace('\n', '')
import re
if not re.search(r'emp_df\[\[[^\]]+\]\]', code_str):
    raise AssertionError('Task 3: Use double brackets [[]] to select multiple columns - correct syntax is emp_df[["Name","Salary"]]')

# Check for .iloc usage
found_iloc = False
for node in ast.walk(tree):
    if isinstance(node, ast.Attribute) and node.attr == 'iloc':
        found_iloc = True

if not found_iloc:
    raise AssertionError('Task 4: Missing .iloc usage')

# Check for .loc usage
found_loc = False
for node in ast.walk(tree):
    if isinstance(node, ast.Attribute) and node.attr == 'loc':
        found_loc = True

if not found_loc:
    raise AssertionError('Task 5: Missing .loc usage')

# Check for boolean filtering with &
found_filter = False
if '&' in user_code and 'Department' in user_code and 'Salary' in user_code:
    found_filter = True

if not found_filter:
    raise AssertionError('Task 6: Missing boolean filter with & operator')

# Check for .isin() usage
found_isin = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'isin':
        found_isin = True

if not found_isin:
    raise AssertionError('Task 7: Missing .isin() usage')

print('TEST_PASSED')
